// ArchiveObject runs the :execrows query against postgresql.
func (q *postgresqlQueries) ArchiveObject(ctx context.Context, db DBTX, arg ArchiveObjectParams) (int64, error) {
	result, err := db.ExecContext(ctx, q.archiveObject,
		arg.ID,
		arg.Scope,
	)
	if err != nil {
		return 0, err
	}

	return result.RowsAffected()
}

